// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz the from address and the length of the _tos array (we'll construct array with at least one entry)
    function testFuzz_property(address from, address fakeRecipient) public {
        // Keep parameters wide but ensure fakeRecipient is not zero (address(0) would be pointless)
        vm.assume(fakeRecipient != address(0));

        // Deploy a helper that will always revert when called with the expected selector
        Reverter reverter = new Reverter();

        // Build a single-element _tos array so exactly one external call is made (simpler observation)
        address[] memory tos = new address[](1);
        tos[0] = address(reverter);

        // Call c.transfer and observe whether it reverts. For the correct contract it MUST revert because
        // the callee reverts; the mutant will catch the failed call and still return true, so the call will succeed.
        bool ok;
        try c.transfer(from, address(reverter), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY admissible inputs (non-empty tos), the reference contract always reverts
        // when the callee reverts. Therefore ok must be false. The mutant will produce ok == true for some inputs
        // (when callee reverts) and so will fail this assertion.
        assertTrue(!ok);
    }
}

// adversarial helper that reverts when called with the transferFrom selector
contract Reverter {
    // declare the expected function so ABI-decoding routes here when C uses encodeWithSelector.
    function transferFrom(address, address, uint256) external pure {
        revert("bad");
    }

    // also ensure fallback reverts in case of mismatched calldata
    fallback() external payable {
        revert("bad");
    }
}
